window.RP_SESSION={"id":"S-a6bb946b914a","messages":[{"id":"RP-II-0081992","time":"2026-04-13T11:23:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"······ 끙. 눈을 뜨고서는 천천히 일어납니다. 어제 너무 울어서 머리가 띵해. 제 옆에 가만히 누워있는 션 바라보고. 쪽, 가벼운 입맞춤 볼에 합니다. 슬슬 준비하고 나가야지···.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0081993","time":"2026-04-13T11:26:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"어제 옷도 갈아입지 못하고 그대로인 상태. 션과 떨어지자마자 곧바로 머리가 무거워지는 듯한 느낌입니다. 괜찮을 거야, 하며 옆에 놓인 차가운 물 마시고.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0081994","time":"2026-04-13T11:29:00+09:00","room":"RP II","name":"션","profile":"델타인","identity":"reviewed","type":"dialogue","body":"그거 술인데.","characters":["P-3bbc4a823df9"]},{"id":"RP-II-0081995","time":"2026-04-13T11:30:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"프헵, 뿜으려는 것··· 겨우 참아 삼킵니다. 션은 자고 있다···. 오래간만에 잠이다······. 조심히 몸 일으켜서 항상 가지고 다니는 제 유리펜 뽑았습니다. 조금이라도 서류 처리를 도와야 한다","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0081996","time":"2026-04-13T11:30:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"양피지 한 장과 서류를 옆에 둡니다. 서류 뽑아들고 간단한 요약하고, 또 읽고 가벼운 요약하고···.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0081997","time":"2026-04-13T11:31:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"빠른 속도로 끝내갑니다, 비서 일을 했어서 참 다행이라는 생각 하고···.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0081998","time":"2026-04-13T11:33:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"······ ** 누가 침대 옆에 술을 나둬.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0081999","time":"2026-04-13T11:34:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"주르륵 늘여집니다······.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0082000","time":"2026-04-13T11:36:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"아침부터 술 마실 생각으로 옆에 두는거야······? 항상 티나 물을 옆에 두던 마리우스로서는 전혀 이해가 가지 않습니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0082001","time":"2026-04-13T11:36:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"머리도 아프고, 힘들고······.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0082002","time":"2026-04-13T11:39:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0082003","time":"2026-04-13T11:39:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
